targets.rawSql:
select to_timestamp(time) as time, agent || ' (' || model || ')' as metric, edge_vs_cash_pct as value
from agent_scores where run_id in ($run) and horizon = '$horizon' and $__unixEpochFilter(time)
order by 1

select agent, model, coalesce(stance || coalesce(' toward ' || toward, ''), 'none shown') as stance, count(*) as looks
from agent_looks where run_id in ($run)
group by 1, 2, 3 order by 1, 3
